// Apple artwork is generated by the documented Sign in with Apple button endpoint.
// https://developer.apple.com/documentation/signinwithapplerestapi/get-a-sign-in-with-apple-button-that-is-center-aligned.
// Google G is the official artwork from https://developers.google.com/identity/branding-guidelines.
// Embedded PNGs keep the sign-in UI available without requests to either provider on page load.
const apple_en_US_black = 'data:image/png;base64,';
const apple_en_US_white = 'data:image/png;base64,';
const apple_ja_JP_black = 'data:image/png;base64,';
const apple_ja_JP_white = 'data:image/png;base64,';
export const GOOGLE_SIGN_IN_LOGO = 'data:image/png;base64,';

export const PROVIDER_BUTTON_STYLE = `
body{--sttd-apple-art:url(${apple_en_US_black})}
html[lang=ja] body{--sttd-apple-art:url(${apple_ja_JP_black})}
@media(prefers-color-scheme:dark){
  body:not(.sttd-light-only){--sttd-apple-art:url(${apple_en_US_white})}
  html[lang=ja] body:not(.sttd-light-only){--sttd-apple-art:url(${apple_ja_JP_white})}
}
button.sttd-provider{width:240px;max-width:100%;min-height:44px;border-radius:6px;box-sizing:border-box}
button.sttd-apple,button.sttd-apple:hover,button.sttd-apple:disabled{
  padding:0;border:0;background:var(--sttd-apple-art) center/contain no-repeat
}
button.sttd-apple .sttd-provider-label{
  position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap
}
button.sttd-google{
  display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:0 12px;
  border:1px solid #747775;background:#fff;color:#1f1f1f;
  font:500 14px/20px "Google Sans",Roboto,Arial,sans-serif
}
button.sttd-google[hidden]{display:none}
button.sttd-google:hover{background:#f8faff;color:#1f1f1f;border-color:#747775}
button.sttd-google img{width:20px;height:20px;flex:none}
@media(prefers-color-scheme:dark){
  body:not(.sttd-light-only) button.sttd-google{background:#131314;color:#e3e3e3;border-color:#8e918f}
  body:not(.sttd-light-only) button.sttd-google:hover{background:#202124}
}
button.sttd-provider:disabled,button.sttd-provider:disabled:hover{opacity:.48;cursor:not-allowed}
@media(forced-colors:active){
  button.sttd-apple,button.sttd-apple:hover,button.sttd-apple:disabled{
    border:1px solid ButtonText;background:ButtonFace;color:ButtonText
  }
  button.sttd-apple .sttd-provider-label{position:static;width:auto;height:auto;clip-path:none;white-space:normal}
}
`;
